import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const supportedRange = ">=22.18 <25";

const authoritativeDocuments = [
  ["SSOT", "docs/north-star/agent-operator-score-ssot-v1.0.md"],
  ["ADR-0003", "docs/adr/ADR-0003-runtime-repository-and-distribution.md"],
  ["D0 PRD", "docs/prd/PRD-D0-name-migration-and-repository-skeleton.md"]
];

const nodeMatrix = (workflow) => {
  const inline = workflow.match(/^\s*node:\s*\[([^\]]+)]/m);
  if (inline) {
    return inline[1].split(",").map((value) => value.trim().replace(/["']/g, ""));
  }

  const block = workflow.match(/^\s*node:\s*\n((?:\s*-\s*[^\n]+\n?)+)/m);
  if (block) {
    return [...block[1].matchAll(/^\s*-\s*([^\s#]+).*$/gm)]
      .map((match) => match[1].replace(/["']/g, ""));
  }

  return [];
};

test("published Node runtime contract is consistent", () => {
  const manifest = JSON.parse(readFileSync(resolve(repositoryRoot, "package.json"), "utf8"));
  assert.equal(manifest.engines?.node, supportedRange);

  const workflow = readFileSync(resolve(repositoryRoot, ".github/workflows/ci.yml"), "utf8");
  assert.deepEqual(nodeMatrix(workflow), ["22", "24"]);

  for (const [name, path] of authoritativeDocuments) {
    const document = readFileSync(resolve(repositoryRoot, path), "utf8");
    assert.ok(
      document.includes(supportedRange),
      `${name} does not publish the supported Node range ${supportedRange}`
    );
  }
});
